            test("energy full sink never extracts",new Runnable(){public void run(){setupEnergy();fluidNode(-1).energy.receive(1000,false);fluidNode(3).energy.receive(100000,false);check(fluidNode(0).transferOnce()==0&&fluidNode(-1).energy.stored()==1000,"full sink conservation");}});
