            test("opaque export all pages reconstruct original native bytes",new Runnable(){public void run(){NBTTagCompound original=opaqueExportFixture(300);java.io.ByteArrayOutputStream expected=new java.io.ByteArrayOutputStream();try{net.minecraft.nbt.CompressedStreamTools.write(original,new java.io.DataOutputStream(expected));}catch(java.io.IOException bad){throw new RuntimeException(bad);}byte[] raw=expected.toByteArray();StringBuilder actual=new StringBuilder();int pages=(raw.length+127)/128;for(int page=1;page<=pages;page++){String row=LegacyWirelessSafety.opaqueExport(world,chatPlayer(false,true),page)[1];actual.append(row.substring(row.indexOf(" hex ")+5));for(String line:LegacyWirelessSafety.opaqueExport(world,chatPlayer(false,true),page))System.out.println("PL4 OPAQUE EXPORT BLOCK "+page+" "+line);}StringBuilder hex=new StringBuilder();for(byte b:raw)hex.append(String.format(java.util.Locale.ROOT,"%02x",b&255));check(hex.toString().equals(actual.toString()),"full original nested payload without invented route");System.out.println("PL4 OPAQUE EXPORT "+LegacyWirelessSafety.opaqueExport(world,chatPlayer(false,true),1)[0]);}});
