    private NBTTagCompound opaqueExportFixture(int length){NBTTagCompound tag=new NBTTagCompound();tag.setInteger("Schema",99);tag.setString("OriginalTarget","unknown");NBTTagCompound nested=new NBTTagCompound();byte[] raw=new byte[length];for(int i=0;i<length;i++)raw[i]=(byte)(i%251);nested.setByteArray("OriginalBytes",raw);tag.setTag("OriginalEvidence",nested);LegacyWirelessSafety.data(world).readFromNBT(tag);return tag;}
    private LegacyTile historicalFault(){LegacyTile n=node(export);n.pending=readerStack(8);NBTTagCompound tag=saveFluid(n);tag.setString("ItemTransferFault","Historical insertion outcome unknown");tag.setInteger("ItemEscrowCount",8);tag.removeTag("ItemJournalContext");tag.removeTag("ItemLegacyEvidence");n.readFromNBT(tag);return n;}
    private void test(String name,Runnable body){total++;JsonObject result=new JsonObject();result.addProperty("name",name);try{reset();body.run();passed++;result.addProperty("passed",true);}catch(Throwable error){result.addProperty("passed",false);result.addProperty("error",error.toString());error.printStackTrace();}results.add(result);}
    private void reset(){NBTTagCompound journalBlank=new NBTTagCompound();journalBlank.setInteger("Schema",1);journalBlank.setTag("Entries",new net.minecraft.nbt.NBTTagList());LegacyWirelessSafety.data(world).readFromNBT(journalBlank);LegacyWirelessSafety.data(world).markDirty();LegacyPL4.energyEnabled=true;LegacyPL4.energyRate=400;LegacyPL4.manualEnergy=40;LegacyPL4.fluidsEnabled=true;LegacyPL4.fluidRate=250;LegacyPL4.enabled=true;LegacyPL4.nodeLimit=256;LegacyPL4.slotLimit=256;LegacyPL4.itemRate=8;for(int x=-2;x<=4;x++)for(int y=199;y<=202;y++)for(int z=-1;z<=1;z++){world.getChunkFromBlockCoords(new BlockPos(x,y,z));world.setBlockToAir(new BlockPos(x,y,z));}for(EntityItem item:world.getEntitiesWithinAABB(EntityItem.class,new AxisAlignedBB(-3,198,-3,6,204,3)))item.setDead();LegacyWirelessSafety.data(world).readFromNBT(journalBlank);LegacyWirelessSafety.data(world).markDirty();world.setBlockState(export,LegacyPL4.EXPORT.getDefaultState(),3);world.setBlockState(cable,LegacyPL4.CABLE.getDefaultState(),3);world.setBlockState(sink,LegacyPL4.IMPORT.getDefaultState(),3);for(BlockPos p:new BlockPos[]{export,cable,sink})node(p).owner=OWNER.toString();node(export).side=4;node(sink).side=5;world.setBlockState(export.west(),Blocks.CHEST.getDefaultState(),3);world.setBlockState(sink.east(),Blocks.CHEST.getDefaultState(),3);}
