    public static final class ExternalEnergy extends TileEntity implements net.minecraftforge.energy.IEnergyStorage {
        int energy,executed;boolean deny,refuse,fail,bad;
        @Override public boolean hasCapability(net.minecraftforge.common.capabilities.Capability<?> cap,net.minecraft.util.EnumFacing side){return cap==net.minecraftforge.energy.CapabilityEnergy.ENERGY&&!deny&&side==net.minecraft.util.EnumFacing.WEST;}
        @Override public <T> T getCapability(net.minecraftforge.common.capabilities.Capability<T> cap,net.minecraft.util.EnumFacing side){return hasCapability(cap,side)?net.minecraftforge.energy.CapabilityEnergy.ENERGY.cast(this):null;}
        public int receiveEnergy(int n,boolean simulate){if(simulate&&bad)return n+1;int take=Math.min(n,100000-energy);if(!simulate){executed++;if(refuse)return 0;energy+=take;if(fail)throw new IllegalStateException("energy failure after mutation");}return take;}
        public int extractEnergy(int n,boolean simulate){int take=Math.min(n,energy);if(!simulate)energy-=take;return take;}
        public int getEnergyStored(){return energy;}public int getMaxEnergyStored(){return 100000;}
        public boolean canExtract(){return !deny;}public boolean canReceive(){return !deny;}
    }


